package agenttrace

import "time"

// HandoffCheckpoint mirrors the schema generated by Handoff (.handoff/checkpoint.json).
type HandoffCheckpoint struct {
	SessionID      string    `json:"session_id"`
	Agent          string    `json:"agent"`
	Model          string    `json:"model"`
	Objective      string    `json:"objective"`
	Timestamp      time.Time `json:"timestamp"`
	ModifiedFiles  []string  `json:"modified_files,omitempty"`
	LastCommand    string    `json:"last_command,omitempty"`
	LastExitCode   int       `json:"last_exit_code,omitempty"`
	UnfinishedWork string    `json:"unfinished_work,omitempty"`
}

// HandoffEvent represents an event record appended to .handoff/events.json.
type HandoffEvent struct {
	Type        string    `json:"type"` // e.g. "nextdeploy_ship_start", "nextdeploy_build_error", "nextdeploy_ship_success", "nextdeploy_probe_failure"
	Timestamp   time.Time `json:"timestamp"`
	Source      string    `json:"source"`                // "nextdeploy"
	Target      string    `json:"target,omitempty"`      // "vps", "cloudflare", "aws"
	Environment string    `json:"environment,omitempty"` // "production", "preview"
	Details     string    `json:"details,omitempty"`
	LiveURL     string    `json:"live_url,omitempty"`
	ErrorCode   string    `json:"error_code,omitempty"`
	ErrorMsg    string    `json:"error_msg,omitempty"`
	Route       string    `json:"route,omitempty"`
	FixHint     string    `json:"fix_hint,omitempty"`
}

// DeploymentProvenance is embedded into release metadata or logs to track which agent session built it.
type DeploymentProvenance struct {
	SessionID string `json:"session_id,omitempty"`
	Agent     string `json:"agent,omitempty"`
	Model     string `json:"model,omitempty"`
	Objective string `json:"objective,omitempty"`
}
